 "content": "from collections import defaultdict


def transform(grid):
    # Treat each distinct nonzero color as one motif; crop its occupied bbox.
    positions = defaultdict(list)
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                positions[value].append((r, c))

    motifs = []
    for color in sorted(positions):
        cells = positions[color]
        r0 = min(r for r, _ in cells)
        r1 = max(r for r, _ in cells)
        c0 = min(c for _, c in cells)
        c1 = max(c for _, c in cells)
        motif = [[color if (r, c) in set(cells) else 0
                  for c in range(c0, c1 + 1)]
                 for r in range(r0, r1 + 1)]
        motifs.append(motif)

    height = max((len(motif) for motif in motifs), default=0)
    output = [[] for _ in range(height)]
    for motif in motifs:
        width = len(motif[0])
        top = (height - len(motif)) // 2
        for r in range(height):
            if top <= r < top + len(motif):
                output[r].extend(motif[r - top])
            else:
                output[r].extend([0] * width)
    return output
